// v234 : page /rapport servie au telephone (rapport de bug : capture de la tele, etat, dernieres actions)
static const char rapport_page[] =
"<!doctype html><html lang=\"fr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n"
"<title>GC Station - rapport</title><style>\n"
":root{--bg:#0f0b22;--card:#1c1638;--line:#33295e;--fg:#eee9ff;--dim:#a79ccf;--acc:#8b5cff}\n"
"*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.4 system-ui,sans-serif}\n"
".w{max-width:640px;margin:0 auto;padding:12px 14px 40px}h1{font-size:20px;margin:4px 0 4px}a{color:var(--acc)}\n"
".card{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:14px;margin-bottom:12px}\n"
"h3{margin:0 0 8px;font-size:16px}.h{color:var(--dim);font-size:13px}\n"
"#cap{width:100%;border-radius:8px;display:block;background:#000;aspect-ratio:4/3}\n"
"pre{white-space:pre-wrap;word-break:break-word;font-size:12px;line-height:1.35;margin:0;max-height:50vh;overflow:auto;background:#130e2a;padding:10px;border-radius:8px}\n"
".row{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}\n"
"button{font:inherit;color:var(--fg);background:#2a2150;border:1px solid var(--line);border-radius:10px;padding:10px 14px;min-height:44px}\n"
"button.big{background:var(--acc);border:0;font-weight:700;flex:1}\n"
"textarea{width:100%;font:inherit;padding:10px;border-radius:10px;border:1px solid var(--line);background:#130e2a;color:var(--fg);min-height:80px}\n"
"</style></head><body><div class=\"w\"><h1>Rapport de bug</h1><p class=\"h\">Tout ce qu'il faut pour expliquer un souci : ce qu'affiche la télé, l'état de GC Station et ses dernières actions. Rien n'est envoyé tout seul : tu télécharges le rapport et tu le partages.</p>\n"
"<div class=\"card\"><h3>Ce qui ne va pas</h3><textarea id=\"d\" placeholder=\"Ce que tu faisais, ce qui s'est passé, ce que tu attendais…\"></textarea></div>\n"
"<div class=\"card\"><h3>L'écran de la télé</h3><img id=\"cap\" alt=\"capture de la télé\"><div class=\"row\"><button onclick=\"cap()\">Nouvelle capture</button></div><div class=\"h\" id=\"cm\"></div></div>\n"
"<div class=\"card\"><h3>GC Station</h3><pre id=\"i\">…</pre></div>\n"
"<div class=\"card\"><h3>Dernières actions et plantages</h3><pre id=\"j\">…</pre></div>\n"
"<div class=\"card\" id=\"tc\" hidden><h3>Dernier test de la console</h3><pre id=\"tt\">…</pre></div>\n"
"<div class=\"row\"><button class=\"big\" onclick=\"dl()\">Télécharger le rapport</button></div>\n"
"<p class=\"h\">Le rapport est un seul fichier (page web avec la capture) : envoie-le tel quel. <a href=\"/\">← Télécommande</a></p></div><script>\n"
"function $(i){return document.getElementById(i)}\n"
"var CAP=\"\",INFO=\"\",JOUR=\"\";\n"
"function cap(){$(\"cm\").textContent=\"Capture…\";var im=new Image();im.onload=()=>{var c=document.createElement(\"canvas\");c.width=im.naturalWidth;c.height=im.naturalHeight;c.getContext(\"2d\").drawImage(im,0,0);CAP=c.toDataURL(\"image/png\");$(\"cap\").src=CAP;$(\"cm\").textContent=\"Capture prise à \"+new Date().toLocaleTimeString()};im.onerror=()=>{$(\"cm\").textContent=\"Capture impossible\"};im.src=\"/capture.bmp?t=\"+Date.now()}\n"
"function mo(b){return(b/1048576).toFixed(1).replace(\".\",\",\")+\" Mo\"}\n"
"function info(){Promise.all([fetch(\"/api/memoire\").then(r=>r.json()),fetch(\"/api/state\").then(r=>r.json())]).then(a=>{var m=a[0],s=a[1];\n"
"var t=\"GC Station \"+m.ver+\" (build \"+m.build+\"), allumée depuis \"+Math.floor(m.up/60)+\" min\\n\";\n"
"t+=\"Mémoire : libre \"+mo(m.free)+\", utilisée \"+mo(m.used)+(m.big?\", plus grand bloc \"+mo(m.big):\"\")+\"\\n\";\n"
"if(m.tabs.length)t+=\"Le moins de mémoire libre par onglet : \"+m.tabs.map(x=>x[0]+\" \"+mo(x[1]*1024)).join(\", \")+\"\\n\";\n"
"if(m.boot)t+=\"Dernier démarrage : \"+(m.boot/1000).toFixed(1).replace(\".\",\",\")+\" s (\"+m.steps.map(x=>x[0]+\" \"+x[1]+\" ms\").join(\", \")+\")\\n\";\n"
"t+=\"En cours : \"+s.title+(s.sub?\" – \"+s.sub:\"\")+(s.web?\"\\nPage ouverte : \"+s.web:\"\")+\"\\n\";\n"
"t+=\"Téléphone : \"+navigator.userAgent;INFO=t;$(\"i\").textContent=t}).catch(()=>{$(\"i\").textContent=\"Pas de réponse de la GameCube\"})}\n"
"function jour(){fetch(\"/api/journal\").then(r=>r.text()).then(t=>{JOUR=t;$(\"j\").textContent=t}).catch(()=>{$(\"j\").textContent=\"Pas de réponse de la GameCube\"})}\n"
"function esc(x){return x.replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\")}\n"
"function dl(){var d=new Date(),p=n=>(n<10?\"0\":\"\")+n,st=d.getFullYear()+\"-\"+p(d.getMonth()+1)+\"-\"+p(d.getDate())+\" \"+p(d.getHours())+\":\"+p(d.getMinutes());\n"
"var h=\"<!doctype html><meta charset=utf-8><title>Rapport GC Station \"+st+\"</title><body style='font:15px system-ui;background:#111;color:#eee;max-width:720px;margin:auto;padding:16px'><h1>Rapport GC Station</h1><p>\"+st+\"</p><h2>Ce qui ne va pas</h2><p style='white-space:pre-wrap'>\"+esc($(\"d\").value||\"(rien d'écrit)\")+\"</p>\"+(CAP?\"<h2>Écran de la télé</h2><img style='width:100%' src='\"+CAP+\"'>\":\"\")+\"<h2>GC Station</h2><pre style='white-space:pre-wrap'>\"+esc(INFO)+\"</pre><h2>Dernières actions et plantages</h2><pre style='white-space:pre-wrap'>\"+esc(JOUR)+\"</pre>\"+(TEST?\"<h2>Dernier test de la console</h2><pre style='white-space:pre-wrap'>\"+esc(TEST)+\"</pre>\":\"\")+\"</body>\";\n"
"var a=document.createElement(\"a\");a.href=URL.createObjectURL(new Blob([h],{type:\"text/html\"}));a.download=\"rapport-gcstation-\"+st.replace(/[ :]/g,\"-\")+\".html\";document.body.appendChild(a);a.click();a.remove()}\n"
"var TEST=\"\";function test(){fetch(\"/test.txt\").then(r=>r.ok?r.text():\"\").then(t=>{if(!t)return;TEST=t.replace(/^#mesures.*\\n/,\"\");$(\"tt\").textContent=TEST;$(\"tc\").hidden=false}).catch(()=>{})}\n"
"cap();info();jour();test();\n"
"</script></body></html>\n"
"\n"
;
